    defaults: {'in-process'},
  ),
  HostCapability.jsApps: (
    all: {'browser', 'extension-subset'},
    defaults: {'browser'},
  ),
  HostCapability.checkpointRewind: (
    all: {'file', 'origin-storage'},
    defaults: {'file'},
  ),
  HostCapability.hostExtensionApi: (all: {}, defaults: {}),

