  HostCapability.configSections: (
    all: {'file', 'origin-storage'},
    defaults: {'file'},
  ),
  HostCapability.compaction: (
    all: {'session-root', 'origin-storage'},
    defaults: {'session-root'},
  ),
  HostCapability.loadModes: (
    all: {'project-scan', 'registered-only'},
