  HostCapability.visionTranscribe: (all: {}, defaults: {}),
  HostCapability.subagents: (all: {}, defaults: {}),
  HostCapability.browserBridge: (all: {}, defaults: {}),
  HostCapability.jsExtensions: (all: {}, defaults: {}),
