  profile: cliProfile,
  services: AgentCoreServices(
    baseEnv: _env,
    sessionEnvVars: _sessionEnvVars,
    sandbox: SandboxServices(
      spec: config.cubeSpec,
      homeDir: config.homeDir,
      os: config.osName,
