      // rides the same transient-ENOENT retry, logged to fa.log.
      sessionIoRetry: SessionIoRetryConfig(logger: _logDiagnostic),
    ),
    extRuntimeFactory: config.extRuntimeFactory,
    sessionRoot: config.sessionRoot,
