          'edit',
          'ls',
          'bash',
          'memory_add',
          'schedule_message',
          'ask',
          'request_secret',
          'generate_image',
          'generate_video',
        ]),
      );
      // Core builtins first, host tools last: the registry must see the
      // same registration order as the hand-rolled constructor produced.
      expect(wired.tools.first.name, 'read');
    });

